import {bones,tendons,structures} from './anatomy.js';
import {createJoints,setPose} from './joints.js';
import {createBone} from './model.js';
import {createTendon,updateTendon} from './tendons.js';
const $=id=>document.getElementById(id);
const state={selected:null,hidden:new Set(),bones:true,tendons:true,ligaments:true,opacity:1,isolate:false,context:true,labels:false,dorsi:0,invert:0,playing:false,speed:.5};
let renderer;
try{renderer=new T.WebGLRenderer({antialias:!matchMedia('(pointer:coarse)').matches,alpha:true,powerPreference:'low-power'});}catch(e){renderer=new CompatibilityRenderer();}
const mobile=matchMedia('(pointer:coarse)').matches;renderer.setPixelRatio(Math.min(devicePixelRatio,mobile?1.5:2));renderer.setClearColor(0x000000,0);renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;$('canvasHost').appendChild(renderer.domElement);
renderer.domElement.setAttribute('aria-label','Right ankle and foot. Drag to rotate, pinch to zoom, two fingers to pan. Tap a structure to select.');
const scene=new T.Scene(),camera=new T.PerspectiveCamera(37,1,.1,250),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.dampingFactor=.09;controls.minDistance=6;controls.maxDistance=95;controls.maxPolarAngle=Math.PI;controls.touches.ONE=T.TOUCH.ROTATE;controls.touches.TWO=T.TOUCH.DOLLY_PAN;controls.screenSpacePanning=true;
scene.add(new T.HemisphereLight(0xd9edff,0x716654,2.2));const key=new T.DirectionalLight(0xfff2dc,3.0);key.position.set(-12,26,18);scene.add(key);const rim=new T.DirectionalLight(0x85bdd8,2);rim.position.set(16,14,-16);scene.add(rim);
const joints=createJoints(scene),boneRecords=bones.map(b=>createBone(b,joints)),tendonRecords=tendons.map(t=>createTendon(t,joints,scene));const ligamentRecords=ligaments.map(l=>createLigament(l,joints,scene));const records=[...boneRecords,...tendonRecords,...ligamentRecords],byId=new Map(records.map(r=>[r.data.id,r]));scene.updateMatrixWorld(true);
let poseDirty=true,renderDirty=true,lost=false,last=0,phase=0,slowFrames=0,segments=renderer.isCompatibility?32:mobile?48:64;
controls.addEventListener('change',()=>renderDirty=true);
function updatePose(){setPose(joints,state.dorsi,state.invert);for(const b of boneRecords){b.inverse=b.group.matrixWorld.clone().invert();}for(const t of tendonRecords)updateTendon(t,boneRecords,segments);for(const l of ligamentRecords)updateLigament(l);poseDirty=false;}
function visible(r){return !state.hidden.has(r.data.id)&&(r.data.layer==='bone'?state.bones:r.data.layer==='ligament'?state.ligaments:state.tendons);}
function updateAppearance(){renderDirty=true;for(const r of records){const selected=r.data.id===state.selected;let show=visible(r),opacity=r.data.layer==='bone'?state.opacity:1;if(state.isolate&&!selected){show=show&&state.context&&r.data.layer==='bone';opacity=.075;}r.group.visible=show;r.material.opacity=opacity;r.material.color.setHex(selected?0x65d6d2:r.data.layer==='bone'?0xe8dfc9:r.data.layer==='ligament'?0xf2c45d:0xd48c68);r.material.emissive.setHex(selected?0x174a4a:0x000000);r.material.depthWrite=opacity>.95;r.meshes.forEach(m=>m.renderOrder=r.data.layer==='bone'?0:1);}renderList();}
function select(id){state.selected=id;const r=byId.get(id);$('selectedName').textContent=r?.data.name||'Explore the anatomy';$('selectedDescription').textContent=r?.data.description||'Tap a bone, tendon, or ligament to inspect it.';$('focus').disabled=!r;$('isolate').disabled=!r;updateAppearance();}
function renderList(){const query=$('search').value.toLowerCase();const filtered=structures.filter(s=>(s.name+' '+s.description).toLowerCase().includes(query));$('count').textContent=filtered.length+' items';$('structureList').replaceChildren();for(const layer of ['bone','tendon','ligament']){const items=filtered.filter(s=>s.layer===layer);if(!items.length)continue;const h=document.createElement('div');h.className='list-section';h.textContent=layer==='bone'?'Bones':layer==='ligament'?'Ligaments':'Tendons';$('structureList').append(h);for(const s of items){const row=document.createElement('div');row.className='structure'+(s.id===state.selected?' selected':'');const b=document.createElement('button');b.textContent=s.name;b.setAttribute('aria-pressed',s.id===state.selected);b.onclick=()=>select(s.id);const eye=document.createElement('button');eye.className='visibility';const isHidden=state.hidden.has(s.id);eye.textContent=isHidden?'○':'●';eye.setAttribute('aria-label',(isHidden?'Show ':'Hide ')+s.name);eye.setAttribute('aria-pressed',!isHidden);eye.onclick=()=>{if(isHidden)state.hidden.delete(s.id);else state.hidden.add(s.id);updateAppearance();};row.append(b,eye);$('structureList').append(row);}}if(!filtered.length)$('structureList').textContent='No matching structures.';}
$('search').oninput=renderList;
$('ligamentView').onclick=()=>{state.bones=true;state.tendons=false;state.ligaments=true;state.opacity=.22;state.isolate=false;
for(const l of ligaments)state.hidden.delete(l.id);
$('boneLayer').checked=true;$('tendonLayer').checked=false;$('ligamentLayer').checked=true;$('isolate').checked=false;$('opacity').value=22;$('opacityValue').textContent='22%';select('atfl');
fit(new T.Vector3(0,4,1),6.5,new T.Vector3(1,.3,1));};
for(const [id,key] of [['boneLayer','bones'],['tendonLayer','tendons'],['ligamentLayer','ligaments'],['isolate','isolate'],['context','context'],['showLabels','labels']])$(id).onchange=e=>{state[key]=e.target.checked;updateAppearance();};
$('opacity').oninput=e=>{state.opacity=+e.target.value/100;$('opacityValue').textContent=e.target.value+'%';updateAppearance();};
function syncAngles(){for(const [id,key,out] of [['dorsi','dorsi','dorsiValue'],['invert','invert','invertValue']]){$(id).value=state[key];$(out).textContent=(state[key]>0?'+':'')+Math.round(state[key])+'°';}}
function stop(){state.playing=false;$('play').textContent='▶ Play';}
for(const id of ['dorsi','invert'])$(id).oninput=e=>{stop();state[id]=+e.target.value;poseDirty=true;syncAngles();};
$('neutral').onclick=()=>{stop();phase=0;state.dorsi=state.invert=0;poseDirty=true;syncAngles();};
$('play').onclick=()=>{state.playing=!state.playing;$('play').textContent=state.playing?'Ⅱ Pause':'▶ Play';};
$('speed').oninput=e=>{state.speed=+e.target.value;$('speedValue').textContent=state.speed+'×';};
const center=new T.Vector3(0,8,5);
function frame(){const box=new T.Box3();for(const r of records)if(r.group.visible)box.expandByObject(r.group);if(box.isEmpty())return {target:center.clone(),radius:14};const sphere=box.getBoundingSphere(new T.Sphere());return {target:sphere.center,radius:sphere.radius};}
function fit(target,radius,direction){const vertical=T.MathUtils.degToRad(camera.fov),horizontal=2*Math.atan(Math.tan(vertical/2)*camera.aspect);const distance=radius/Math.sin(Math.min(vertical,horizontal)/2)*1.2;controls.target.copy(target);camera.position.copy(target).add(direction.clone().normalize().multiplyScalar(Math.min(92,Math.max(9,distance))));controls.update();}
const directions={front:[0,0,1],back:[0,0,-1],medial:[-1,0,0],lateral:[1,0,0],top:[0,1,.001],sole:[0,-1,.001]};
function resetCamera(){const f=frame();fit(f.target,f.radius,new T.Vector3(1,.55,1.05));document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('active'));}
$('resetCamera').onclick=resetCamera;
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{const f=frame();fit(f.target,f.radius,new T.Vector3(...directions[b.dataset.view]));document.querySelectorAll('[data-view]').forEach(v=>v.classList.toggle('active',v===b));});
$('focus').onclick=()=>{const r=byId.get(state.selected);if(!r)return;state.hidden.delete(r.data.id);if(r.data.layer==='bone'){state.bones=true;$('boneLayer').checked=true;}else if(r.data.layer==='ligament'){state.ligaments=true;$('ligamentLayer').checked=true;}else{state.tendons=true;$('tendonLayer').checked=true;}updateAppearance();const s=new T.Box3().setFromObject(r.group).getBoundingSphere(new T.Sphere());fit(s.center,Math.max(s.radius,1.5),camera.position.clone().sub(controls.target));};
const ray=new T.Raycaster(),pointer=new T.Vector2();let down=null,multi=false,activePointers=new Set();const canvas=renderer.domElement;
canvas.addEventListener('pointerdown',e=>{activePointers.add(e.pointerId);if(activePointers.size>1)multi=true;if(activePointers.size===1){multi=false;down={x:e.clientX,y:e.clientY,time:performance.now()};}});
canvas.addEventListener('pointerup',e=>{activePointers.delete(e.pointerId);if(!down||multi||Math.hypot(e.clientX-down.x,e.clientY-down.y)>6||performance.now()-down.time>650)return;const rect=canvas.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,camera);const meshes=records.filter(r=>r.group.visible&&r.material.opacity>.1&&!(r.data.layer==='bone'&&state.opacity<=.3)).flatMap(r=>r.meshes);const hit=ray.intersectObjects(meshes,false)[0];if(hit)select(hit.object.userData.id);down=null;});
canvas.addEventListener('pointercancel',e=>{activePointers.delete(e.pointerId);down=null;});canvas.addEventListener('contextmenu',e=>e.preventDefault());for(const type of ['gesturestart','gesturechange','gestureend'])canvas.addEventListener(type,e=>e.preventDefault(),{passive:false});
function resize(){renderDirty=true;const rect=$('canvasHost').getBoundingClientRect();if(!rect.width||!rect.height)return;camera.aspect=rect.width/rect.height;camera.updateProjectionMatrix();renderer.setSize(rect.width,rect.height,false);}
new ResizeObserver(resize).observe($('canvasHost'));resize();updatePose();updateAppearance();resetCamera();
function labels(){const host=$('labels'),svg=$('leaders');host.replaceChildren();svg.replaceChildren();if(!state.labels)return;const w=host.clientWidth,h=host.clientHeight;let candidates=records.filter(r=>r.group.visible&&r.material.opacity>.1);if(state.selected)candidates.sort((a,b)=>(b.data.id===state.selected)-(a.data.id===state.selected));candidates=candidates.slice(0,mobile?5:8);candidates.forEach((r,i)=>{const p=new T.Box3().setFromObject(r.group).getCenter(new T.Vector3()).project(camera);if(p.z>1||p.z< -1)return;const x=(p.x+1)*w/2,y=(1-p.y)*h/2;const tx=i%2?Math.max(10,w-170):12,ty=120+Math.floor(i/2)*43;if(ty>h-170)return;const label=document.createElement('span');label.className='anatomy-label';label.textContent=r.data.name;label.style.left=tx+'px';label.style.top=ty+'px';host.append(label);const line=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v] of Object.entries({x1:x,y1:y,x2:tx+20,y2:ty+12,stroke:'#86b7ba','stroke-width':1}))line.setAttribute(k,v);svg.append(line);});}
canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();lost=true;stop();$('status').textContent='3D graphics paused. Waiting for Safari to restore WebGL…';});canvas.addEventListener('webglcontextrestored',()=>{lost=false;poseDirty=true;resize();$('status').textContent='';});
document.addEventListener('visibilitychange',()=>{last=0;});
function animate(now){requestAnimationFrame(animate);if(lost||document.hidden)return;const dt=last?Math.min((now-last)/1000,.1):0;last=now;if(dt>.04)slowFrames++;else slowFrames=Math.max(0,slowFrames-1);if(slowFrames>90&&renderer.getPixelRatio()>1){renderer.setPixelRatio(1);segments=40;poseDirty=true;slowFrames=0;}if(state.playing){phase+=dt*state.speed*.9;state.dorsi=12*Math.sin(phase);state.invert=8*Math.sin(phase*.7);poseDirty=true;syncAngles();}if(poseDirty){updatePose();renderDirty=true;}controls.update();if(!renderer.isCompatibility||renderDirty){labels();renderer.render(scene,camera);renderDirty=false;}}
requestAnimationFrame(animate);$('status').textContent=renderer.isCompatibility?'Compatibility rendering · WebGL unavailable':'';
$('aboutBtn').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();
document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('open',p.id===b.dataset.panel));document.querySelectorAll('[data-panel]').forEach(p=>p.classList.toggle('active',p===b));resize();});
